import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry conv2d_kernel(
    .param .u64 input_ptr,
    .param .u64 weight_ptr,
    .param .u64 bias_ptr,
    .param .u64 output_ptr,
    .param .u32 total_elements
)
{
    .reg .pred %p<11>;
    .reg .s32 %r<80>;
    .reg .s64 %rd<40>;
    .reg .f32 %f<15>;

    ld.param.u64 %rd1, [input_ptr];
    ld.param.u64 %rd2, [weight_ptr];
    ld.param.u64 %rd3, [bias_ptr];
    ld.param.u64 %rd4, [output_ptr];
    ld.param.u32 %r1, [total_elements];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    cvta.to.global.u64 %rd4, %rd4;

    mov.u32 %r2, %ctaid.x;
    mov.u32 %r3, %ntid.x;
    mov.u32 %r4, %tid.x;
    mad.lo.u32 %r5, %r2, %r3, %r4;

    setp.ge.u32 %p1, %r5, %r1;
    @%p1 bra DONE;

    mov.u32 %r10, %r5;
    mov.u32 %r11, 55;
    rem.u32 %r12, %r10, %r11;
    div.u32 %r13, %r10, %r11;
    rem.u32 %r14, %r13, %r11;
    div.u32 %r15, %r13, %r11;
    mov.u32 %r16, 96;
    rem.u32 %r17, %r15, %r16;
    div.u32 %r18, %r15, %r16;

    mul.lo.s32 %r20, %r14, 4;
    sub.s32 %r20, %r20, 2;
    mul.lo.s32 %r21, %r12, 4;
    sub.s32 %r21, %r21, 2;

    mul.wide.s32 %rd11, %r17, 4;
    add.s64 %rd12, %rd3, %rd11;
    ld.global.f32 %f1, [%rd12];

    mov.s32 %r30, 0;

LOOP_IC:
    setp.ge.s32 %p2, %r30, 3;
    @%p2 bra END_IC;

    mov.s32 %r31, 0;

LOOP_KH:
    setp.ge.s32 %p3, %r31, 11;
    @%p3 bra END_KH;

    add.s32 %r40, %r20, %r31;
    setp.lt.s32 %p4, %r40, 0;
    setp.ge.s32 %p5, %r40, 224;
    or.pred %p6, %p4, %p5;
    @%p6 bra SKIP_KH;

    mov.s32 %r32, 0;

LOOP_KW:
    setp.ge.s32 %p7, %r32, 11;
    @%p7 bra END_KW;

    add.s32 %r41, %r21, %r32;
    setp.lt.s32 %p8, %r41, 0;
    setp.ge.s32 %p9, %r41, 224;
    or.pred %p10, %p8, %p9;
    @%p10 bra SKIP_KW;

    mad.lo.s32 %r50, %r18, 3, %r30;
    mad.lo.s32 %r51, %r50, 224, %r40;
    mad.lo.s32 %r52, %r51, 224, %r41;
    mul.wide.s32 %rd20, %r52, 4;
    add.s64 %rd21, %rd1, %rd20;
    ld.global.f32 %f10, [%rd21];

    mad.lo.s32 %r53, %r17, 3, %r30;
    mad.lo.s32 %r54, %r53, 11, %r31;
    mad.lo.s32 %r55, %r54, 11, %r32;
    mul.wide.s32 %rd22, %r55, 4;
    add.s64 %rd23, %rd2, %rd22;
    ld.global.f32 %f11, [%rd23];

    fma.rn.f32 %f1, %f10, %f11, %f1;

SKIP_KW:
    add.s32 %r32, %r32, 1;
    bra LOOP_KW;

END_KW:
SKIP_KH:
    add.s32 %r31, %r31, 1;
    bra LOOP_KH;

END_KH:
    add.s32 %r30, %r30, 1;
    bra LOOP_IC;

END_IC:
    mul.wide.u32 %rd30, %r5, 4;
    add.s64 %rd31, %rd4, %rd30;
    st.global.f32 [%rd31], %f1;

DONE:
    ret;
}
