    def __init__(self, num_classes=1000):
        super().__init__()
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)

    def forward(self, x):
        assert x.is_cuda
        x = x.contiguous()
        weight = self.conv1.weight.contiguous()
        bias = self.conv1.bias.contiguous()

        N, C, H, W = x.shape
        out_h = (H + 2 * 2 - 11) // 4 + 1
        out_w = (W + 2 * 2 - 11) // 4 + 1
        out_channels = weight.shape[0]

        output = torch.empty((N, out_channels, out_h, out_w), device=x.device, dtype=x.dtype)

        total_elements = N * out_channels * out_h * out_w

        module = _get_ptx_module()

        block_x = 256
        grid_x = (total_elements + block_x - 1) // block_x

        module.launch(
            "conv2d_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x, weight, bias, output, i32(total_elements)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )

        return output

